/// <summary>
///  CB232_AutoSettingItemStockStatus.
/// Find by reference.
/// </summary>
/// <param name = "_inventItemInventSetupRecId">_inventItemInventSetupRecId</param>
/// <param name = "_forUpdate">_forUpdate</param>
/// <returns>METInventItemInventSetup</returns>
static public METInventItemInventSetup find(RefRecId _inventItemInventSetupRecId, boolean _forUpdate = false)
{
    METInventItemInventSetup metInventItemInventSetup;
    
    if (_inventItemInventSetupRecId)
    {
        metInventItemInventSetup.selectForUpdate(_forUpdate);
        select firstonly metInventItemInventSetup
            where metInventItemInventSetup.InventItemInventSetup  == _inventItemInventSetupRecId;
    }
    
    return metInventItemInventSetup;
}

    /// <summary>
    /// CB232_AutoSettingItemStockStatus.
    /// Gets <c>METInventItemInventSetup</c> record by item and site Ids.
    /// </summary>
    /// <param name = "_itemId">Item Id.</param>
    /// <param name = "_siteId">Site id.</param>
    /// <param name = "_forUpdate">forUpdate.</param>
    /// <returns> <c>METInventItemStatusSetup</c> record. </returns>
    public static METInventItemInventSetup findByItemAndSite(ItemId _itemId, InventSiteId _siteId, boolean _forUpdate = false)
    {
        InventItemInventSetup itemSetup;
        InventDim             inventDim;
        
        itemSetup.selectForUpdate(_forUpdate);

        select firstonly itemSetup
            where itemSetup.ItemId == _itemId
            exists join inventDim
                where inventDim.InventDimId  == itemSetup.InventDimId
                &&    inventDim.InventSiteId == _siteId;

        return itemSetup.metInventItemInventSetup();
    }

    /// <summary>
    /// CB232_AutoSettingItemStockStatus.
    /// Resets item stock status from LTNA to blank.
    /// </summary>
    /// <param name = "_itemId">Item Id.</param>
    /// <param name = "_siteId">Site Id.</param>
    public static void resetItemStockLTNAStatus(ItemId _itemId, InventSiteId _siteId)
    {
        #OCCRetryCount
        EcoResProductLifecycleState productLifecycleState;
        InventItemInventSetup       itemSetup;
        METInventItemInventSetup    metItemSetup;
        InventDim                   inventDim;

        select firstonly metItemSetup
            exists join itemSetup
                where itemSetup.RecId == metItemSetup.InventItemInventSetup
                &&    itemSetup.ItemId == _itemId
            exists join inventDim
                where inventDim.InventDimId  == itemSetup.InventDimId
                &&    inventDim.InventSiteId == _siteId
            exists join productLifecycleState
                where productLifecycleState.StateId   == metItemSetup.ProductLifecycleStateId
                &&    productLifecycleState.METStatus == METEcoResProductLifecycleStateStatus::LTNA;

        if (!metItemSetup)
        {
            return;
        }

        try
        {
            ttsbegin;

            metItemSetup.selectForUpdate(true);
        
            //Empties the field.
            metItemSetup.ProductLifecycleStateId = '';
            metItemSetup.update();

            ttscommit;
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
    }

